      // Check your conditions here
      if (this.$store.getters.GetDirectoryForm === false && this.formActionType !== "initiate" && this.formActionType !== "preview" || this.formActionType !== "initiate" && this.formActionType !== "preview" && this.$store.getters.GetDirectoryForm === true && this.Idx !== 0) {
